            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_opp_count += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22
    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if very_urgent:
        bid = max(62.0, highest_prev + 2.0)
        if supply_tight:
            bid = max(bid, 76.0)
        return float(min(budget, bid))

    if my_urgent:
        bid = max(52.0, avg_prev + 2.0)
        if highest_prev >= 75.0:
            bid = max(bid, highest_prev + 1.0)
        if supply_tight:
            bid += 6.0
        return float(min(budget, bid))

    if supply_loose and urgent_opp_count == 0:
        return float(min(budget, 24.0))

    if supply_loose:
        bid = 28.0 if highest_prev < 60.0 else 34.0
        return float(min(budget, bid))

    if supply_tight:
        if highest_prev >= 78.0:
            bid = 41.0
        elif highest_prev >= 60.0:
            bid = highest_prev + 1.5
        else:
            bid = 49.0 + min(6.0, float(rich_opp_count))
        return float(min(budget, bid))

    bid = 36.0
    if highest_prev >= 75.0:
        bid = 33.0
    elif highest_prev >= 58.0:
        bid = highest_prev + 1.0
    elif avg_prev > 0:
        bid = max(38.0, avg_prev - 3.0)

    if day >= 8 and hp >= 6 and budget < DAILY_SALARY * 2:
        bid -= 4.0

    bid = max(0.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from active opponents (immediate reaction)
    yesterday_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure heuristic: when supply is low, water is scarce -> bid higher.
    # We avoid extreme bidding to exploit opponent overreaction.
    if supply <= (MIN_SUPPLY + 1):
        pressure = 1.0
    elif supply <= (MIN_SUPPLY + 4):
        pressure = 0.85
    elif supply <= (MIN_SUPPLY + 8):
        pressure = 0.7
    else:
        pressure = 0.55

    # If we've already gone without water, increase bid sharply to reset risk.
    if no_water_days >= 2:
        urgency = 1.0
    elif no_water_days == 1:
        urgency = 0.85
    else:
        urgency = 0.65

    # If our hp is critically low, prioritize survival.
    if hp <= 2:
        hp_factor = 1.0
    elif hp <= 4:
        hp_factor = 0.9
    elif hp <= 6:
        hp_factor = 0.75
    else:
        hp_factor = 0.6

    # Opponent reaction exploitation: if they bid very high yesterday, they likely overcommitted.
    # We bid enough to compete, but not match their peak unless we are in danger.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Their peak suggests they are willing to spend heavily; reduce slightly when our hp is safe.
        opponent_factor = 0.78 if hp > 3 else 0.95
    elif avg_prev_bid >= DAILY_SALARY * 0.6:
        opponent_factor = 0.85
    else:
        opponent_factor = 0.7

    target = DAILY_SALARY * pressure * urgency * hp_factor * opponent_factor

    # Cap bid to budget and avoid wasting when budget is low.
    # Also keep a floor so we don't always lose to mid bidders.
    min_floor = DAILY_SALARY * (0.25 if hp > 5 else 0.55)
    bid = max(min_floor, target)
    bid = min(bid, budget)

    # If budget is extremely low, just bid what we can.
    if budget <= 1e-6:
        return 0.0

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

